-- 01_edgar_company_facts_create.sql), one REST table and one flattened view per public
-- supplier, with the revenue tag verified by scripts/verify_ciks.py.
-- Terms: declared User-Agent required (the runner fills the placeholder from
-- ZETARIS_USER_AGENT), at most 10 requests/s, query live, no bulk redistribution.
-- Run one statement at a time (run_sql.py --skip-exists). On HTTP 429 wait 60 s and
-- run the file once more with --skip-exists; created objects are skipped.
-- REST tables carry the tag in their name and views are CREATE OR REPLACE, so a tag
-- change adds a new table and repoints the view; nothing is dropped. Tables of a
-- replaced tag can be removed by hand in the Data Explorer.

CREATE LIGHTNING DATABASE SR_EDGAR DESCRIBE BY "SEC EDGAR revenue facts of the public suppliers";

CREATE SCHEMASTORE CONTAINER sr_edgar;

-- S0001 Texas Instruments Incorporated, CIK 0000097476, us-gaap RevenueFromContractWithCustomerExcludingAssessedTax
CREATE LIGHTNING REST TABLE s0001_rfc_excl_tax_facts FROM SR_EDGAR REQUEST(
    endpoint "https://data.sec.gov/api/xbrl/companyconcept/CIK0000097476/us-gaap/RevenueFromContractWithCustomerExcludingAssessedTax.json",
    method "get",
    response_type "json",
    http_encoding "URLENCODED"
) HEADER (
    user-agent "YOUR_APP_NAME YOUR_CONTACT_EMAIL"
) BODY ();

CREATE OR REPLACE SCHEMASTORE VIEW s0001_revenue WITH CONTAINER sr_edgar AS
SELECT
    cik,
    tag AS concept,
    fact.`start` AS period_start,
    fact.`end` AS period_end,
    fact.val AS value_usd,
    fact.accn AS accession_number,
    fact.fy AS fiscal_year,
    fact.fp AS fiscal_period,
    fact.frame AS period_frame,
    fact.form AS form_type,
    fact.filed AS filed_date
FROM sr_edgar.s0001_rfc_excl_tax_facts
LATERAL VIEW explode(units.USD) AS fact;

